#include "PlanetaryEventRuntime.hpp"
namespace elysium::world { static StableId mix(std::uint64_t a,std::uint64_t b,std::uint64_t c){a^=b+0x9e3779b97f4a7c15ULL+(a<<6)+(a>>2);a^=c+0xbf58476d1ce4e5b9ULL+(a<<7)+(a>>3);return a?a:1;} bool PlanetaryEventRuntime::registerTemplate(EventTemplate d,std::string&w){if(!d.id||!d.version||!d.warningTicks||!d.maxConcurrent){w="invalid template";return false;}if(!defs_.emplace(d.id,std::move(d)).second){w="duplicate template";return false;}return true;} std::optional<EventInstance> PlanetaryEventRuntime::begin(ContentId t,std::uint64_t addr,std::uint64_t tick,std::uint64_t seed,std::string&w){auto d=defs_.find(t);if(d==defs_.end()){w="unknown template";return std::nullopt;}if(cooldownUntil_[addr]>tick){w="cooldown";return std::nullopt;}std::size_t n=0;for(auto&[_,e]:live_)if(e.address==addr&&e.templateId==t&&e.phase!=EventPhase::Completed)++n;if(n>=d->second.maxConcurrent){w="event cap";return std::nullopt;}EventInstance e{mix(t,addr,seed),t,addr,seed,tick};live_[e.id]=e;return e;} std::vector<EventInstance> PlanetaryEventRuntime::advance(std::uint64_t tick){std::vector<EventInstance> changed;for(auto&[_,e]:live_){auto&d=defs_.at(e.templateId);auto age=tick-e.startTick;if(e.phase==EventPhase::Warning&&age>=d.warningTicks){e.phase=EventPhase::Active;changed.push_back(e);}if(e.phase==EventPhase::Active&&d.activeTicks&&age>=std::uint64_t(d.warningTicks)+d.activeTicks){e.phase=EventPhase::Completed;cooldownUntil_[e.address]=tick+d.cooldownTicks;changed.push_back(e);}}return changed;} bool PlanetaryEventRuntime::settle(StableId id,std::string&w){auto i=live_.find(id);if(i==live_.end()){w="unknown event";return false;}if(i->second.settled){w="already settled";return false;}if(i->second.phase!=EventPhase::Completed){w="not complete";return false;}i->second.settled=true;return true;} }